def compute(vars):
    total_obligations = vars["v1"]
    interest_component = vars["v2"]
    principal_only = total_obligations - interest_component

    return {
        "value": principal_only,
        "trace": {
            "total_obligations": total_obligations,
            "interest_component": interest_component,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
